import { useIntl } from 'react-intl';

import { BasicContainer, NoDataYet } from 'components';

import { StyledEmptyStateContainer } from './CommercialResultsEmptyState.styles';

type CommercialResultsPageStateVariant = 'empty' | 'error';

interface CommercialResultsEmptyStateProps {
  dataTestId?: string;
  variant?: CommercialResultsPageStateVariant;
}

const VARIANT_CONFIG: Record<
  CommercialResultsPageStateVariant,
  {
    defaultTestId: string;
    titleId?: string;
    descriptionId: string;
  }
> = {
  empty: {
    defaultTestId: 'commercial-results-empty-state',
    descriptionId: 'ValueCreation.CommercialResults.emptyState.description',
  },
  error: {
    defaultTestId: 'commercial-results-error-state',
    descriptionId: 'ValueCreation.CommercialResults.errorState.description',
  },
};

export const CommercialResultsEmptyState: React.FC<
  CommercialResultsEmptyStateProps
> = ({ dataTestId, variant = 'empty' }) => {
  const { formatMessage } = useIntl();
  const config = VARIANT_CONFIG[variant];

  const title = config.titleId
    ? formatMessage({ id: config.titleId })
    : undefined;
  const description = formatMessage({ id: config.descriptionId });

  return (
    <BasicContainer
      fullWidth={true}
      data-testid={dataTestId ?? config.defaultTestId}
    >
      <StyledEmptyStateContainer>
        <NoDataYet
          title={title}
          description={description}
          illustration="noDataAvailable"
          size="auto"
          fontSize="large"
        />
      </StyledEmptyStateContainer>
    </BasicContainer>
  );
};
